solution.code:
function compose(...fns) {
  return function (x) {
    return fns.reduceRight((acc, fn) => fn(acc), x);
  };
}

const inc = x => x + 1;
const double = x => x * 2;
const incThenDouble = compose(double, inc);
console.log(incThenDouble(3)); // 8

